-- MZO BO7 Aetherium in-game HUD (2026-11-04): a skin over the Aetherium widgets. They keep all their data (models,
-- swap fades, low ammo, downed); this only moves, restyles and adds to them, so the layout comes from one place:
-- MZOBO7GameHud*.lua, generated by _tools/Kxboo Greyhound/tools/bo7/runs/zm_menus/scripts/build_hud.py (1:1 with the
-- user's BO7 screenshots, method in _handoff/bo7-zm-menus.md). Each widget's new() ends with a pcall of H.<Widget>.
-- Zone: zm_mod (it only runs in a game).

-- real Lua errors from here on: the HUD's first widgets build before HUDInject's SetupMatch turns this on, and an error
-- in them was a bare "UI Error <number>". Turning it on twice is fine (the DLL patches once)
pcall( function ()
	require( "ui.util.MZO_Hook" ).enable_lua_trace()
end )

require( "ui.uieditor.menus.Lobby.BO7.MZOBO7Kit" )
require( "ui.uieditor.widgets.HUD.AetheriumWidgets.BO7.MZOBO7GameHud" )

local K = CoD.MZOBO7Kit
CoD.MZOBO7Hud = CoD.MZOBO7Hud or {}
local H = CoD.MZOBO7Hud

local function noop()
end

local function part( name )
	return CoD.MZOBO7Layout["MZOBO7GameHud_" .. name] or {}
end

-- hide: subscriptions keep resetting alpha, so scale is the only thing that stays
local function hide( widget, names )
	for i = 1, #names do
		local e = widget[names[i]]
		if e then
			e:setScale( 0 )
		end
	end
end

-- box in BO3 units; the widget's own setLeftRight / setTopBottom calls do nothing from now on (its moves were for the
-- old layout: shield slide, empty-equipment shift, score growth)
local function place( e, l, t, r, b )
	e:setLeftRight( true, false, l, r )
	e:setTopBottom( true, false, t, b )
	e.setLeftRight = noop
	e.setTopBottom = noop
end

-- BO7's armor pip art: the widget's own setImage calls do nothing from now on, and it alone decides their alpha
local ARMOR = {}
for i = 0, 2 do
	ARMOR["pl_armor" .. i] = true
	ARMOR["pl_armor_o" .. i] = true
end

-- an existing element takes a layout entry's box, font, alignment and colour. The widget sets plain white whenever
-- its state resets: that now means the entry's colour. Other colours (low ammo red, downed red) pass through.
local function skinElement( e, d )
	place( e, d.l, d.t, d.r, d.b )
	if d.id == "ld_theme" or d.id == "pl_hp_fill" or d.id == "pm_hp_fill" or ARMOR[d.id] then
		e:setImage( RegisterImage( d.img ) )
	end
	if ARMOR[d.id] then
		e.setImage = noop
	end
	if d.zr then
		e:setZRot( d.zr )
	end
	if d.k == "txt" then
		e:setTTF( K.FONTS[d.f] or K.FONTS.R )
		if d.al == 1 then
			e:setAlignment( Enum.LUIAlignment.LUI_ALIGNMENT_CENTER )
		elseif d.al == 2 then
			e:setAlignment( Enum.LUIAlignment.LUI_ALIGNMENT_RIGHT )
		else
			e:setAlignment( Enum.LUIAlignment.LUI_ALIGNMENT_LEFT )
		end
	end
	if d.a and d.a > 0 and not ARMOR[d.id] then
		e:setAlpha( d.a )
	end
	if d.rgb then
		local r0, g0, b0 = K.rgbOf( d.rgb )
		local setRGB = e.setRGB
		setRGB( e, r0, g0, b0 )
		e.setRGB = function ( self, r, g, b )
			if r == 1 and g == 1 and b == 1 then
				r, g, b = r0, g0, b0
			end
			setRGB( self, r, g, b )
		end
	end
end

-- walks a layout part back to front: mapped entries restyle the widget's element, the rest are built just below the
-- next one up, so the part's draw order holds around the widget's own elements. Returns the built elements by id.
local function skin( widget, name, map, skipIds )
	local layout = part( name )
	local els = {}
	local above = nil
	for i = #layout, 1, -1 do
		local d = layout[i]
		local e = map[d.id] and widget[map[d.id]]
		if e then
			skinElement( e, d )
			above = e
		elseif not ( skipIds and skipIds[d.id] ) then
			local holder = LUI.UIElement.new()
			local built = K.build( holder, { d } )
			local new = built[d.id]
			holder:removeElement( new )
			if d.zr then
				new:setZRot( d.zr )
			end
			if above then
				new:addElementBefore( above )
			else
				widget:addElement( new )
			end
			els[d.id] = new
			above = new
		end
	end
	return els
end

local function boxOf( name, id )
	local layout = part( name )
	for i = 1, #layout do
		if layout[i].id == id then
			return layout[i]
		end
	end
end

-- strip the widget's "+" from a count (BO7 shows a plain number)
local function plainCount( e )
	local setText = e.setText
	e.setText = function ( self, text )
		setText( self, ( string.gsub( tostring( text ), "%+", "" ) ) )
	end
end

-- calls fn( alpha ) as well whenever the widget sets e's alpha
local function followAlpha( e, fn )
	local setAlpha = e.setAlpha
	e.setAlpha = function ( self, a )
		setAlpha( self, a )
		fn( a )
	end
end

local function setShown( list, a )
	for i = 1, #list do
		if list[i] then
			list[i]:setAlpha( a )
		end
	end
end

function H.Loadout( self, controller )
	local els = skin( self, "Loadout", {
		ld_theme = "loadout", ld_weapon = "weapon_icon", ld_wname = "weapon_name", ld_clip = "ammo_clip",
		ld_stock = "ammo_stock", ld_lethal = "lethal_icon", ld_lethal_n = "lethal_count",
		ld_tactical = "tactical_icon", ld_tactical_n = "tactical_count"
	}, { ld_field = true, ld_fu_meter = true } )
	hide( self, { "rarity_glow", "rarity_bar", "rarity_label", "lethal_bg", "tactical_bg" } )
	place( self.ammo_mod_icon, 1500 / 1.5, 980 / 1.5, 1524 / 1.5, 1004 / 1.5 )
	place( self.pap_icon, 1470 / 1.5, 880 / 1.5, 1500 / 1.5, 910 / 1.5 )

	-- the weapon's slide is gone (BO7 only fades), and the widget's smaller equipment box stays square in the orb
	local w = boxOf( "Loadout", "ld_weapon" )
	local cx, cy = ( w.l + w.r ) / 2, ( w.t + w.b ) / 2
	local leftRight, topBottom = LUI.UIElement.setLeftRight, LUI.UIElement.setTopBottom
	self.weapon_icon.setLeftRight = function ( e, a, b, l, r )
		if r - l == 56 then
			leftRight( e, true, false, cx - 28, cx + 28 )
		else
			leftRight( e, true, false, w.l, w.r )
		end
	end
	self.weapon_icon.setTopBottom = function ( e, a, b, t, bottom )
		if bottom - t == 56 then
			topBottom( e, true, false, cy - 28, cy + 28 )
		else
			topBottom( e, true, false, w.t, w.b )
		end
	end

	-- BO7's AmmoCounter draws the clip three times, the red / cyan ones just off the white one
	local setClip = self.ammo_clip.setText
	self.ammo_clip.setText = function ( e, text )
		setClip( e, text )
		els.ld_clip_r:setText( text )
		els.ld_clip_c:setText( text )
	end
	plainCount( self.lethal_count )
	plainCount( self.tactical_count )

	-- the orange arc over the orb lights while that equipment has charges (AvailableHighlight)
	followAlpha( self.lethal_count, function ( a )
		els.ld_arc_l:setAlpha( a )
	end )
	followAlpha( self.tactical_count, function ( a )
		els.ld_arc_r:setAlpha( a )
	end )
	els.ld_arc_r:setAlpha( 0 )

	-- BO7's tier tag behind the name: the widget's tier colours, hidden on the base tier (BO7's alpha = the tier number)
	local tierModel = Engine.CreateModel( Engine.GetModelForController( controller ), "t10_weapon_upgrade_tier" )
	els.ld_wtag:subscribeToModel( tierModel, function ( model )
		local tier = tonumber( Engine.GetModelValue( model ) ) or 0
		local rarity = CoD.AetheriumLoadout.RarityColor( tier )
		els.ld_wtag:setRGB( rarity.r, rarity.g, rarity.b )
		els.ld_wtag:setAlpha( tier > 0 and 1 or 0 )
	end )
end

-- player 1..4: number disc fill and ring
local PARTY_RGB = {
	{ 0x0c8c10, 0x2ec84a },
	{ 0xe0d614, 0xf4ec40 },
	{ 0x1eb4e0, 0x50d0f4 },
	{ 0xf050b8, 0xff80d0 }
}

local function paintNumber( num, disc, ring, text )
	local rgb = PARTY_RGB[num + 1] or PARTY_RGB[1]
	if disc then
		disc:setRGB( K.rgbOf( rgb[1] ) )
	end
	if ring then
		ring:setRGB( K.rgbOf( rgb[2] ) )
	end
	if text then
		text:setText( tostring( num + 1 ) )
	end
end

function H.PlayerInfo( self, controller )
	local els = skin( self, "Player", {
		pl_theme = "player", pl_portrait = "player_portrait", pl_name = "player_name", pl_hp = "player_hp",
		pl_salv_i = "salvage_icon", pl_salv = "salvage_amount", pl_ess_i = "points_icon", pl_ess = "points_amount",
		pl_plate = "armor_reserve_icon", pl_plate_n = "armor_reserve_count", pl_hp_fill = "health_fill",
		pl_armor0 = "armor_plate_1", pl_armor1 = "armor_plate_2", pl_armor2 = "armor_plate_3",
		pl_armor_o0 = "armor_plate_1_outline", pl_armor_o1 = "armor_plate_2_outline",
		pl_armor_o2 = "armor_plate_3_outline"
	} )
	hide( self, { "health_border", "armor_reserve_max" } )
	-- the widget shows a lost plate at 0.35: BO7 shows only its outline
	for i = 1, 3 do
		local plate = self["armor_plate_" .. i]
		local setAlpha = plate.setAlpha
		plate.setAlpha = function ( e, a )
			setAlpha( e, a < 1 and 0 or a )
		end
	end
	plainCount( self.armor_reserve_count )
	followAlpha( self.armor_reserve_count, function ( a )
		setShown( { els.pl_plate_n_bg, els.pl_item_key_bg, els.pl_item_key }, a )
	end )
	setShown( { els.pl_plate_n_bg, els.pl_item_key_bg, els.pl_item_key }, 0 )

	-- the band behind the ticks wipes with the HP (BO7 anchors it to the same progress). The red ticks and the end tick
	-- only show below full health
	local glow = els.pl_hp_glow
	local lost, cap = els.pl_hp_lost, els.pl_hp_cap
	local bar, capBox = boxOf( "Player", "pl_hp_lost" ), boxOf( "Player", "pl_hp_cap" )
	local hp, barAlpha = 1, 1
	local function paintLost()
		local on = barAlpha > 0 and hp < 0.995 and 1 or 0
		lost:setAlpha( on )
		cap:setAlpha( on )
		local dx = ( bar.r - bar.l ) * hp
		cap:setLeftRight( true, false, capBox.l + dx, capBox.r + dx )
		cap:setTopBottom( true, false, capBox.t - dx * 0.07, capBox.b - dx * 0.07 )
	end
	glow:setMaterial( LUI.UIImage.GetCachedMaterial( "uie_wipe_normal" ) )
	glow:setShaderVector( 0, 1, 0, 0, 0 )
	glow:setShaderVector( 1, 0, 0, 0, 0 )
	glow:setShaderVector( 2, 1, 0, 0, 0 )
	glow:setShaderVector( 3, 0, 0, 0, 0 )
	local setVector = self.health_fill.setShaderVector
	self.health_fill.setShaderVector = function ( e, n, a, b, c, d )
		setVector( e, n, a, b, c, d )
		glow:setShaderVector( n, a, b, c, d )
		if n == 0 then
			hp = a
			paintLost()
		end
	end
	-- the widget tweens the fill: the band and the end tick move with it
	for _, name in ipairs( { "beginAnimation", "completeAnimation" } ) do
		local original = self.health_fill[name]
		self.health_fill[name] = function ( e, ... )
			glow[name]( glow, ... )
			cap[name]( cap, ... )
			return original( e, ... )
		end
	end
	followAlpha( self.health_fill, function ( a )
		barAlpha = a
		paintLost()
	end )

	-- the shield's bar runs along the armor pips, at their tilt
	local first, last = boxOf( "Player", "pl_armor0" ), boxOf( "Player", "pl_armor2" )
	local mid = ( first.t + last.b ) / 2
	place( self.shield_health_fill, first.l + 1, mid - 1.5, last.r - 1, mid + 1.5 )
	self.shield_health_fill:setZRot( 4.7 )

	-- no BO7 slot for these: the shield sits in the + slot, the downed icon past the HP bar, score popups past the score
	local ring = boxOf( "Player", "pl_item_ring" )
	place( self.shield_icon, ring.l, ring.t, ring.r, ring.b )
	followAlpha( self.shield_icon, function ( a )
		if els.pl_item then
			els.pl_item:setAlpha( 1 - a )
		end
	end )
	place( self.downedIcon, 362 / 1.5, 992 / 1.5, 392 / 1.5, 1022 / 1.5 )
	place( self.pointsDeltaContainer, 344 / 1.5, 1020 / 1.5, 419 / 1.5, 1033 / 1.5 )

	self:linkToElementModel( self, "clientNum", true, function ( model )
		local num = Engine.GetModelValue( model )
		if num then
			paintNumber( num, els.pl_party_bg, els.pl_party, els.pl_party_n )
		end
	end )
end

-- BRHealthAndArmorBarsPartyMember over AetheriumPartyPlayers: index 1 is the bottom row. The widget keeps its data and
-- states. The armor pips are new: the same per-player models as the local player's (_zm_t10_armor.csc)
function H.PartyPlayers( self, controller, index )
	local els = skin( self, "Party" .. index, {
		pm_theme = "bg", pm_portrait = "portrait", pm_name = "name", pm_hp_fill = "health_fill",
		pm_ess_i = "essence_icon", pm_points = "points", pm_downed = "downedIcon"
	} )
	hide( self, { "health_border" } )
	-- the slot stays hidden until the widget's playerScoreShown says it's taken
	setShown( { self.bg, self.portrait, self.name, self.health_fill, self.essence_icon, self.points, self.downedIcon }, 0 )
	local fills, lines = {}, {}
	for i = 1, 3 do
		local fill = els["pm_armor" .. ( i - 1 )]
		fill:setMaterial( LUI.UIImage.GetCachedMaterial( "uie_wipe_normal" ) )
		fill:setShaderVector( 0, 1, 0, 0, 0 )
		fill:setShaderVector( 1, 0, 0, 0, 0 )
		fill:setShaderVector( 2, 1, 0, 0, 0 )
		fill:setShaderVector( 3, 0, 0, 0, 0 )
		fills[i], lines[i] = fill, els["pm_armor_o" .. ( i - 1 )]
	end
	local shown = 0
	local tier, plates, partial = 0, 0, 0
	local function paintArmor()
		for i = 1, 3 do
			lines[i]:setAlpha( shown > 0 and i <= tier and 1 or 0 )
			local amount = 0
			if i <= plates then
				amount = 1
			elseif i == plates + 1 then
				amount = partial
			end
			fills[i]:setShaderVector( 0, amount, 0, 0, 0 )
			fills[i]:setAlpha( shown > 0 and i <= tier and amount > 0 and 1 or 0 )
		end
	end
	local extras = { els.pm_num_bg, els.pm_num_ring, els.pm_num, els.pm_hp_bg }
	setShown( extras, 0 )
	paintArmor()
	followAlpha( self.bg, function ( a )
		shown = a
		setShown( extras, a )
		paintArmor()
	end )

	local root = Engine.GetModelForController( controller )
	local subs = {}
	self:linkToElementModel( self, "clientNum", true, function ( model )
		local num = Engine.GetModelValue( model )
		if not num then
			return
		end
		paintNumber( num, els.pm_num_bg, els.pm_num_ring, els.pm_num )
		for i = 1, #subs do
			self:removeSubscription( subs[i] )
		end
		local function watch( name, set )
			return self:subscribeToModel( Engine.CreateModel( root, name .. num ), function ( m )
				set( tonumber( Engine.GetModelValue( m ) ) or 0 )
				paintArmor()
			end )
		end
		subs = {
			watch( "t10_armor_vest_tier_", function ( v )
				tier = v
			end ),
			watch( "t10_armor_vest_plate_", function ( v )
				plates = v
			end ),
			watch( "t10_armor_vest_health_", function ( v )
				partial = v
			end )
		}
	end )
end

local HEADINGS = { [0] = "N", "NE", "E", "SE", "S", "SW", "W", "NW" }

function H.Compass( self, controller )
	local els = skin( self, "Compass", { cp_theme = "compass_image", cp_strip = "HorizontalCompass" } )
	-- no zone names in BO3's data; shown when a script sets the model (same for the objective below)
	local root = Engine.GetModelForController( controller )
	local function textModel( name, e, shownWith )
		e:setAlpha( 0 )
		e:subscribeToModel( Engine.CreateModel( root, name ), function ( model )
			local text = Engine.GetModelValue( model )
			local on = text ~= nil and text ~= "" and text ~= 0
			if on then
				e:setText( Engine.Localize( text ) )
			end
			setShown( shownWith or { e }, on and 1 or 0 )
		end )
	end
	textModel( "mzoHudZone", els.cp_zone )
	els.cp_head:subscribeToModel( Engine.CreateModel( root, "mzoHudHeading" ), function ( model )
		local index = tonumber( Engine.GetModelValue( model ) ) or 0
		els.cp_head:setText( HEADINGS[index] or "N" )
	end )

	local ob = K.build( self, part( "Objective" ) )
	local all = {}
	for _, e in pairs( ob ) do
		all[#all + 1] = e
	end
	setShown( all, 0 )
	textModel( "mzoHudObjective", ob.ob_head, all )
	textModel( "mzoHudObjectiveDesc", ob.ob_desc )
end

-- BO7's red digits, 0..9
local DIGITS = { [0] = "x_21805d8444a77901", "x_2f7b6cb1b4eb6a", "x_3ed43397b32c4b53", "x_7142a5a653016874",
	"x_6434c18b88a4de76", "x_5b03b37ae6ae6d7e", "x_7581734aca6aac97", "x_50c8b55e51b574d8", "x_1a1dd75e2e0b8fc9",
	"x_3a89d332e5629512" }

function H.RoundCounter( self, controller )
	-- the stock container stays for its round sounds; it just isn't drawn
	self.Rounds:setScale( 0 )
	local els = K.build( self, part( "Round" ) )
	local function paint( round )
		for i = 1, 5 do
			els["rd_mark" .. i]:setAlpha( round <= 5 and i <= round and 1 or 0 )
		end
		local place10 = 100
		for i = 0, 2 do
			local d = els["rd_d" .. i]
			local digit = math.floor( round / place10 ) % 10
			if round > 5 and round >= place10 then
				d:setImage( RegisterImage( "i_mzo_aeth7_" .. DIGITS[digit] ) )
				d:setAlpha( 1 )
			elseif round > 5 and i == 2 then
				d:setImage( RegisterImage( "i_mzo_aeth7_" .. DIGITS[digit] ) )
				d:setAlpha( 1 )
			else
				d:setAlpha( 0 )
			end
			place10 = place10 / 10
		end
	end
	paint( 0 )
	self:subscribeToGlobalModel( controller, "GameScore", "roundsPlayed", function ( model )
		paint( math.max( 0, ( tonumber( Engine.GetModelValue( model ) ) or 1 ) - 1 ) )
	end )
end

-- the Aether Shroud meter stays the widget's own: the whole widget moves down onto BO7's field upgrade circle, and
-- the icon fills the 64 px circle measured on the screenshot (centre 1807,976; the widget's move is added here, so -41)
function H.SpecialWeapon( self )
	self:setTopBottom( true, false, 41 / 1.5, 720 + 41 / 1.5 )
	self.setTopBottom = noop
	hide( self, { "element83", "element84", "element85", "element87" } )
	-- this widget now sits 41 px lower, so its boxes come back up by that
	local function toLayout( e, id )
		local d = boxOf( "Loadout", id )
		place( e, d.l, d.t - 41 / 1.5, d.r, d.b - 41 / 1.5 )
		return d
	end
	toLayout( self.element86, "ld_field" )

	-- FieldUpgradeMeterRound's Progress: BO7's fill at its rotation 45 puts the clock's start on the band's upper left end
	-- and the fill's seam on its lower right end, half way round. The widget's own value runs 0..0.93
	local meter = self.element88
	local d = toLayout( meter, "ld_fu_meter" )
	meter:setImage( RegisterImage( d.img ) )
	meter:setRGB( 1, 1, 1 )
	meter:setZRot( 45 )
	local setVector = meter.setShaderVector
	setVector( meter, 1, 0.5, 0, 0, 0 )
	setVector( meter, 2, 0.5, 0, 0, 0 )
	meter.setShaderVector = function ( e, n, a, b, c, v )
		if n == 0 then
			setVector( e, 0, a / 0.93 * 0.5, b, c, v )
		else
			setVector( e, n, a, b, c, v )
		end
	end
	setVector( meter, 0, 0.5, 0, 0, 0 )
end

-- ping-pongs a description wider than its clip (BO7 scrolls them)
local function marquee( e, overflow )
	e:completeAnimation()
	local d = e.mzoD
	e:setLeftRight( true, false, d.l, d.r )
	if overflow <= 0 then
		return
	end
	local ms = math.max( 1500, overflow * 40 )
	local toEnd = true
	local function step()
		local dx = toEnd and -overflow or 0
		e:beginAnimation( "keyframe", ms, false, false, CoD.TweenType.Linear )
		e:setLeftRight( true, false, d.l + dx, d.r + dx )
		toEnd = not toEnd
	end
	e:registerEventHandler( "transition_complete_keyframe", step )
	step()
end

-- ZMGobbleGumModalList: Y opens the equipped pack (MZOGobbleCatalog, same data as the scoreboard's pack). BO3 holds
-- one gum at a time from the machine, so the held one takes the focus frame and the "Use" and the rest are the list.
function H.GumList( menu, controller )
	if menu.MZOBO7GumRoot then
		return
	end
	local root = LUI.UIElement.new()
	root:setLeftRight( true, true, 0, 0 )
	root:setTopBottom( true, true, 0, 0 )
	root:setAlpha( 0 )
	menu:addElement( root )
	menu.MZOBO7GumRoot = root
	local els = K.build( root, part( "Gum" ) )
	pcall( require, "ui.uieditor.menus.Gobble.MZOGobbleCatalog" )
	local C = CoD.MZOGobbleCatalog
	local focusIds = { "gm_focus_glow", "gm_focus_fill", "gm_focus_frame", "gm_focus_arrow" }

	local function moveFocus( slot )
		for i = 1, #focusIds do
			local e = els[focusIds[i]]
			local d = e.mzoD
			local dy = ( slot - 2 ) * 64 / 1.5
			e:setTopBottom( true, false, d.t + dy, d.b + dy )
			e:setAlpha( e.bo7alpha )
		end
	end

	local function paint()
		C.ensure()
		local pack = C.equippedPack( controller )
		local held = Engine.GetModelValue( Engine.GetModel( Engine.GetModelForController( controller ), "bgb_current" ) )
		local rows = {}
		for slot = 0, 4 do
			local row, itemIndex = C.slotRow( controller, pack, slot )
			if row then
				rows[#rows + 1] = { row = row, item = itemIndex }
			end
		end
		for i = 1, #focusIds do
			els[focusIds[i]]:setAlpha( 0 )
		end
		for i = 0, 4 do
			-- fill from the bottom row up: n rows use the last n
			local r = rows[i - ( 5 - #rows ) + 1]
			local on = r and 1 or 0
			setShown( { els["gm_bg" .. i], els["gm_ring" .. i], els["gm_name" .. i], els["gm_desc" .. i] }, on )
			setShown( { els["gm_icon" .. i], els["gm_use" .. i], els["gm_key" .. i], els["gm_key" .. i .. "_bg"] }, 0 )
			if r then
				local copies = C.owned( controller, r.row.key )
				K.setText( els["gm_name" .. i], Engine.ToUpper( C.displayName( r.row ) ) )
				K.setText( els["gm_desc" .. i], Engine.Localize( r.row.desc ) )
				els["gm_icon" .. i]:setImage( RegisterImage( C.iconFor( r.row, r.item ) ) )
				els["gm_icon" .. i]:setAlpha( ( copies > 0 or r.row.infinite ) and 1 or 0.45 )
				els["gm_icon" .. i]:setRGB( 1, 1, 1 )
				marquee( els["gm_desc" .. i], K.textWidth( els["gm_desc" .. i] ) - 178 / 1.5 )
				if held and held > 0 and r.item == held then
					moveFocus( i )
					els["gm_use" .. i]:setAlpha( 1 )
				end
			end
		end
	end

	local open = false
	K.onKey( menu, controller, "Y", nil, function ()
		if not C then
			return false
		end
		open = not open
		if open then
			pcall( paint )
			root:setAlpha( 1 )
		else
			root:setAlpha( 0 )
			for i = 0, 4 do
				els["gm_desc" .. i]:completeAnimation()
			end
		end
		return true
	end )
end

-- runs steps of { ms, fn } on one element, fn setting the values to animate to (BO7's AnimateSequence keyframes)
local function sequence( e, steps, index )
	index = index or 1
	local step = steps[index]
	if not step then
		e:registerEventHandler( "transition_complete_keyframe", nil )
		return
	end
	e:beginAnimation( "keyframe", step[1], false, false, CoD.TweenType.Linear )
	step[2]()
	e:registerEventHandler( "transition_complete_keyframe", function ( el, event )
		if not event.interrupted then
			sequence( e, steps, index + 1 )
		end
	end )
end

-- ScoreFeed: the running total, then a row per score type, newest on top. A repeat of a type on screen adds to its row
-- ("+105 Enemy Distracted x21"). The animations are ScoreFeedEntry's / ScoreFeedTextRow's / ScoreFeed's keyframes
-- (anims/ in runs/aetherium_hud; BO7 px / 1.5 for x, y):
--   new row   text slides from -300 to 66 over 200 ms under the mask, score alpha 0 -> 1 in 80 ms + scale 3x -> 1x
--             in 180
--   older     rows push down 29 px over 200 ms
--   repeat    the multiplier pops 1.2x over 50 ms, back over 30
--   leaving   scale 1.3x and -22,-7 over 90 ms with alpha 0 (60) 1 (30), then alpha 0 and back in place over 40
--   total     fades in over 150 ms with BG over 250; on leaving holds 100 + 100 to 0; the two flash images run alpha
--             1, 0 (50), 1 (140), 0 (60) and 0, 1 (100), 0 (150) on a new score
-- BO7's row life isn't in the widgets (code-driven): 2.5 s since its last score.
local FEED_PITCH = 29 / 1.5
local FEED_LIFE = 2500
local FEED_YELLOW = { "Critical", "Electric Kill", "Blast Furnace", "Fireworks", "Thunderwall", "Turned" }
local LEAVE_DX, LEAVE_DY = -22 / 1.5, -7 / 1.5

function H.KillFeed( self, controller )
	local els, _, groups = K.build( self, part( "Feed" ) )
	local rows = {}
	local total = 0

	local function slot( i )
		return els["kf_score" .. i], els["kf_clip" .. i], els["kf_clip" .. i .. "_inner"], els["kf_text" .. i],
			els["kf_mult" .. i], groups["kf_clip" .. i]
	end

	local function paintMult( mult, text, count )
		mult:setText( count > 1 and ( "x" .. count ) or "" )
		local x = text.mzoD.l + K.textWidth( text ) + 4 / 1.5
		mult:setLeftRight( true, false, x, x + 40 )
	end

	local function resetSlot( i )
		local score, clip, inner, _, _, g = slot( i )
		local d = score.mzoD
		score:completeAnimation()
		clip:completeAnimation()
		inner:completeAnimation()
		score:setScale( 1 )
		clip:setScale( 1 )
		score:setLeftRight( true, false, d.l, d.r )
		score:setTopBottom( true, false, d.t, d.b )
		clip:setLeftRight( true, false, g.l, g.r )
		clip:setTopBottom( true, false, g.t, g.b )
		inner:setLeftRight( true, false, 0, g.r - g.l )
	end

	local function paint()
		for i = 0, 4 do
			local score, clip, _, text, mult = slot( i )
			local r = rows[i + 1]
			resetSlot( i )
			score:setAlpha( r and 1 or 0 )
			clip:setAlpha( r and 1 or 0 )
			if r then
				score:setText( "+" .. r.score )
				text:setText( r.name )
				text:setRGB( K.rgbOf( r.yellow and 0xe6ea2c or 0xffffff ) )
				paintMult( mult, text, r.count )
			end
		end
	end

	local function flash()
		local a, b = els.kf_flash0, els.kf_flash1
		a:completeAnimation()
		b:completeAnimation()
		a:setAlpha( 1 )
		b:setAlpha( 0 )
		sequence( a, {
			{ 50, function () a:setAlpha( 0 ) end },
			{ 140, function () a:setAlpha( 1 ) end },
			{ 60, function () a:setAlpha( 0 ) end }
		} )
		sequence( b, {
			{ 100, function () b:setAlpha( 1 ) end },
			{ 150, function () b:setAlpha( 0 ) end }
		} )
	end

	local function showTotal()
		els.kf_total:completeAnimation()
		els.kf_bg:completeAnimation()
		els.kf_total:setAlpha( 0 )
		els.kf_total:beginAnimation( "keyframe", 150, false, false, CoD.TweenType.Linear )
		els.kf_total:setAlpha( 1 )
		els.kf_bg:setAlpha( 0 )
		els.kf_bg:beginAnimation( "keyframe", 250, false, false, CoD.TweenType.Linear )
		els.kf_bg:setAlpha( 1 )
	end

	local function hideTotal()
		local t, bg = els.kf_total, els.kf_bg
		sequence( t, {
			{ 100, function () t:setAlpha( 1 ) end },
			{ 100, function () t:setAlpha( 0 ) end }
		} )
		bg:beginAnimation( "keyframe", 200, false, false, CoD.TweenType.Linear )
		bg:setAlpha( 0 )
	end

	-- the row in slot i's leaving keyframes; the slot is repainted once it's done
	local function leave( i, r )
		local score, clip, _, _, _, g = slot( i )
		local d = score.mzoD
		r.dying = K.now() + 130
		sequence( score, {
			{ 60, function ()
				score:setScale( 1.3 )
				score:setLeftRight( true, false, d.l + LEAVE_DX * 60 / 90, d.r + LEAVE_DX * 60 / 90 )
				score:setTopBottom( true, false, d.t + LEAVE_DY * 60 / 90, d.b + LEAVE_DY * 60 / 90 )
				score:setAlpha( 0 )
			end },
			{ 30, function ()
				score:setLeftRight( true, false, d.l + LEAVE_DX, d.r + LEAVE_DX )
				score:setTopBottom( true, false, d.t + LEAVE_DY, d.b + LEAVE_DY )
				score:setAlpha( 1 )
			end },
			{ 40, function ()
				score:setScale( 1 )
				score:setLeftRight( true, false, d.l, d.r )
				score:setTopBottom( true, false, d.t, d.b )
				score:setAlpha( 0 )
			end }
		} )
		sequence( clip, {
			{ 60, function ()
				clip:setScale( 1.3 )
				clip:setLeftRight( true, false, g.l + LEAVE_DX * 60 / 90, g.r + LEAVE_DX * 60 / 90 )
				clip:setTopBottom( true, false, g.t + LEAVE_DY * 60 / 90, g.b + LEAVE_DY * 60 / 90 )
				clip:setAlpha( 0 )
			end },
			{ 30, function ()
				clip:setLeftRight( true, false, g.l + LEAVE_DX, g.r + LEAVE_DX )
				clip:setTopBottom( true, false, g.t + LEAVE_DY, g.b + LEAVE_DY )
				clip:setAlpha( 1 )
			end },
			{ 40, function ()
				clip:setScale( 1 )
				clip:setLeftRight( true, false, g.l, g.r )
				clip:setTopBottom( true, false, g.t, g.b )
				clip:setAlpha( 0 )
			end }
		} )
	end

	local function add( name, points )
		local now = K.now()
		if #rows == 0 then
			showTotal()
		end
		total = total + points
		els.kf_total:setText( tostring( total ) )
		flash()
		for i = 1, #rows do
			local r = rows[i]
			if r.name == name and not r.dying then
				r.score, r.count, r.last = r.score + points, r.count + 1, now
				local score, _, _, text, mult = slot( i - 1 )
				score:setText( "+" .. r.score )
				paintMult( mult, text, r.count )
				sequence( mult, {
					{ 50, function () mult:setScale( 1.2 ) end },
					{ 30, function () mult:setScale( 1 ) end }
				} )
				return
			end
		end
		local yellow = false
		for i = 1, #FEED_YELLOW do
			yellow = yellow or string.find( name, FEED_YELLOW[i], 1, true ) ~= nil
		end
		table.insert( rows, 1, { name = name, score = points, count = 1, last = now, yellow = yellow } )
		rows[6] = nil
		paint()
		for i = 0, #rows - 1 do
			local score, clip, inner, _, _, g = slot( i )
			if i == 0 then
				local w = g.r - g.l
				inner:setLeftRight( true, false, -366 / 1.5, w - 366 / 1.5 )
				inner:beginAnimation( "keyframe", 200, false, false, CoD.TweenType.Linear )
				inner:setLeftRight( true, false, 0, w )
				score:setAlpha( 0 )
				score:setScale( 3 )
				sequence( score, {
					{ 80, function ()
						score:setAlpha( 1 )
						score:setScale( 1 + 2 * ( 100 / 180 ) )
					end },
					{ 100, function () score:setScale( 1 ) end }
				} )
			else
				local d = score.mzoD
				score:setTopBottom( true, false, d.t - FEED_PITCH, d.b - FEED_PITCH )
				score:beginAnimation( "keyframe", 200, false, false, CoD.TweenType.Linear )
				score:setTopBottom( true, false, d.t, d.b )
				clip:setTopBottom( true, false, g.t - FEED_PITCH, g.b - FEED_PITCH )
				clip:beginAnimation( "keyframe", 200, false, false, CoD.TweenType.Linear )
				clip:setTopBottom( true, false, g.t, g.b )
			end
		end
	end

	local function tick()
		if #rows == 0 then
			return
		end
		local now = K.now()
		local removed = false
		for i = #rows, 1, -1 do
			local r = rows[i]
			if r.dying then
				if now >= r.dying then
					table.remove( rows, i )
					removed = true
				end
			elseif now - r.last >= FEED_LIFE then
				leave( i - 1, r )
			end
		end
		if removed then
			paint()
			if #rows == 0 then
				total = 0
				hideTotal()
			end
		end
	end

	els.kf_total:setAlpha( 0 )
	els.kf_bg:setAlpha( 0 )
	paint()
	self:addElement( LUI.UITimer.new( 100, "mzo_bo7_feed_tick", false ) )
	self:registerEventHandler( "mzo_bo7_feed_tick", tick )
	self:subscribeToGlobalModel( controller, "PerController", "scriptNotify", function ( model )
		if Engine.GetModelValue( model ) == "score_event" then
			local data = CoD.GetScriptNotifyData( model )
			local name = Engine.Localize( Engine.GetIString( data[1], "CS_LOCALIZED_STRINGS" ) )
			if name and type( data[2] ) == "number" then
				add( name, data[2] )
			end
		end
	end )
end
